def valid_date(date):
    import re
    # Check if date string is not empty
    if not date:
        return False

    # Split date string into month, day, and year
    month, day, year = map(int, date.split('-'))

    # Check if day is within range for the given month
    if not 1 <= day <= 31:
        return False

    # Check if month is within range
    if not 1 <= month <= 12:
        return False

