def do_algebra(operator, operand):
    # Initialize the result
    result = operand[0]

    # Iterate over the operator list and operand list
    for i in range(len(operator)):
        # Apply the operator to the previous result and the next operand
        if operator[i] == '+':
            result += operand[i + 1]
        elif operator[i] == '-':
            result -= operand[i + 1]
        elif operator[i] == '*':
            result *= operand[i + 1]
        elif operator[i] == '//':
            result //= operand[i + 1]
        elif operator[i] == '**':
            result **= operand[i + 1]

    return result
```

